"""Simulated HLS origin for offline tests (no external network).

* Synthetic, structurally valid MPEG-TS segments (PAT/PMT, H.264 PES with
  PTS, SPS/PPS/IDR NAL units, AC-3 PES) generated in pure Python.
* Optional real H.264 + AC-3 segments generated by ffmpeg (see
  ``ffmpeg_timeline``).
* A threaded HTTP/1.1 origin whose live edge advances in real time and that
  can inject faults: 404 segments, truncated bodies (Content-Length larger
  than the body), rotating tokens, redirects, throttled links, stalled
  connections, stale playlists, playlist errors, batch (burst) updates.
"""
from __future__ import annotations

import os
import re
import shutil
import subprocess
import tempfile
import threading
import time
from dataclasses import dataclass, field
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

PTS_HZ = 90000

# ----------------------------------------------------------------- MPEG-TS


def _crc32_mpeg(data: bytes) -> int:
    crc = 0xFFFFFFFF
    for byte in data:
        crc ^= byte << 24
        for _ in range(8):
            crc = ((crc << 1) ^ 0x04C11DB7) if crc & 0x80000000 else (crc << 1)
            crc &= 0xFFFFFFFF
    return crc


def _section(table_id: int, ext_id: int, body: bytes) -> bytes:
    length = 5 + len(body) + 4
    head = bytes([table_id, 0xB0 | ((length >> 8) & 0x0F), length & 0xFF,
                  ext_id >> 8, ext_id & 0xFF, 0xC1, 0x00, 0x00])
    sec = head + body
    return sec + _crc32_mpeg(sec).to_bytes(4, "big")


def _psi_packet(pid: int, section: bytes, cc: int) -> bytes:
    payload = b"\x00" + section
    payload += b"\xff" * (184 - len(payload))
    return bytes([0x47, 0x40 | (pid >> 8), pid & 0xFF, 0x10 | (cc & 0x0F)]) + payload


def _pts_bytes(pts: int, marker: int = 0x21) -> bytes:
    pts &= (1 << 33) - 1
    return bytes([marker | ((pts >> 29) & 0x0E), (pts >> 22) & 0xFF,
                  ((pts >> 14) & 0xFE) | 1, (pts >> 7) & 0xFF, ((pts << 1) & 0xFE) | 1])


def _pes_packets(pid: int, stream_id: int, pts: int, es: bytes, cc: list) -> list:
    header = b"\x00\x00\x01" + bytes([stream_id]) + b"\x00\x00\x80\x80\x05" + _pts_bytes(pts)
    data = header + es
    out = []
    first = True
    while data:
        chunk = data[:184]
        data = data[184:]
        pusi = 0x40 if first else 0
        first = False
        if len(chunk) < 184:
            stuff = 184 - len(chunk) - 1
            af = bytes([stuff]) + (b"\x00" + b"\xff" * (stuff - 1) if stuff > 0 else b"")
            head = bytes([0x47, pusi | (pid >> 8), pid & 0xFF, 0x30 | cc[0]])
            out.append(head + af + chunk)
        else:
            head = bytes([0x47, pusi | (pid >> 8), pid & 0xFF, 0x10 | cc[0]])
            out.append(head + chunk)
        cc[0] = (cc[0] + 1) & 0x0F
    return out


VIDEO_PID, AUDIO_PID, PMT_PID = 0x100, 0x101, 0x1000


def make_segment(pts_start: int, duration: float, tag: bytes = b"", fps: int = 25,
                 frame_bytes: int = 400, keyframe_first: bool = True) -> bytes:
    """Return a valid TS segment; ``tag`` makes the payload unique."""
    pat = _section(0x00, 1, bytes([0x00, 0x01, 0xE0 | (PMT_PID >> 8), PMT_PID & 0xFF]))
    streams = (bytes([0x1B, 0xE0 | (VIDEO_PID >> 8), VIDEO_PID & 0xFF, 0xF0, 0x00]) +
               bytes([0x81, 0xE0 | (AUDIO_PID >> 8), AUDIO_PID & 0xFF, 0xF0, 0x00]))
    pmt = _section(0x02, 1, bytes([0xE0 | (VIDEO_PID >> 8), VIDEO_PID & 0xFF, 0xF0, 0x00]) + streams)
    packets = [_psi_packet(0, pat, 0), _psi_packet(PMT_PID, pmt, 0)]
    vcc, acc = [0], [0]
    frames = max(1, round(duration * fps))
    step = PTS_HZ // fps
    for i in range(frames):
        pts = pts_start + i * step
        nal = b"\x00\x00\x00\x01\x09\xf0"  # AUD
        if i == 0 and keyframe_first:
            nal += b"\x00\x00\x00\x01\x67\x64\x00\x28" + b"\x00\x00\x00\x01\x68\xee\x3c\x80"
            nal += b"\x00\x00\x00\x01\x65" + tag + b"\x88" * frame_bytes
        else:
            nal += b"\x00\x00\x00\x01\x41" + (tag if i == 0 else b"") + b"\x9a" * (frame_bytes // 3)
        packets += _pes_packets(VIDEO_PID, 0xE0, pts, nal, vcc)
    packets += _pes_packets(AUDIO_PID, 0xBD, pts_start, b"\x0b\x77" + b"\x00" * 300, acc)
    return b"".join(packets)


# ----------------------------------------------------------------- timeline


@dataclass
class Entry:
    seq: int
    name: str
    duration: float
    payload: bytes
    discontinuity: bool = False


def synthetic_timeline(count: int, duration: float, start_seq: int = 0, pts_start: int = 900000,
                       name_fmt: str = "s{seq}.ts", epoch: str = "a", first_index: int = 0,
                       keyframe_first: bool = True) -> list:
    out = []
    for i in range(count):
        seq = start_seq + i
        pts = pts_start + round(i * duration * PTS_HZ)
        payload = make_segment(pts, duration, tag=f"{epoch}:{first_index + i}".encode(),
                               keyframe_first=keyframe_first)
        out.append(Entry(seq, name_fmt.format(seq=seq), duration, payload))
    return out


def ffmpeg_timeline(count: int, hls_time: float = 1.0, size: str = "320x180",
                    pts_offset: float = 0.0, start_seq: int = 0, tag: str = "a",
                    gop_seconds: float | None = None) -> list:
    """Real H.264 + AC-3 segments produced by ffmpeg (keyframe aligned)."""
    if not shutil.which("ffmpeg"):
        raise RuntimeError("ffmpeg not available")
    gop = int(round((gop_seconds or hls_time) * 25))
    work = tempfile.mkdtemp(prefix="hlssim-")
    try:
        cmd = ["ffmpeg", "-hide_banner", "-loglevel", "error", "-y",
               "-f", "lavfi", "-i", f"testsrc2=size={size}:rate=25:duration={count * hls_time + 1}",
               "-f", "lavfi", "-i", f"sine=frequency=440:sample_rate=48000:duration={count * hls_time + 1}",
               "-c:v", "libx264", "-preset", "ultrafast", "-g", str(gop), "-keyint_min", str(gop),
               "-sc_threshold", "0", "-pix_fmt", "yuv420p",
               "-c:a", "ac3", "-b:a", "96k",
               "-output_ts_offset", str(pts_offset),
               "-f", "hls", "-hls_time", str(hls_time), "-hls_list_size", "0",
               "-hls_segment_filename", os.path.join(work, "seg%04d.ts"),
               os.path.join(work, "index.m3u8")]
        subprocess.run(cmd, check=True)
        with open(os.path.join(work, "index.m3u8"), encoding="utf-8") as fh:
            text = fh.read()
        durs = [float(x) for x in re.findall(r"#EXTINF:([0-9.]+)", text)]
        names = re.findall(r"^(seg\d+\.ts)$", text, flags=re.M)
        out = []
        for i, (name, d) in enumerate(zip(names[:count], durs[:count])):
            with open(os.path.join(work, name), "rb") as fh:
                out.append(Entry(start_seq + i, f"{tag}-{name}", d, fh.read()))
        return out
    finally:
        shutil.rmtree(work, ignore_errors=True)


# ----------------------------------------------------------------- origin


@dataclass
class Faults:
    missing: set = field(default_factory=set)           # names -> always 404
    truncate: dict = field(default_factory=dict)        # name -> times to truncate
    stall: dict = field(default_factory=dict)           # name -> times to stall mid-body
    stall_seconds: float = 5.0
    rotate_tokens: bool = False                         # ?token=N on every playlist response
    redirect_master: bool = False                       # master -> 302 -> /edge/... media
    throttle_bps: float = 0.0                           # per connection, bytes/s for segments
    stale_every: int = 0                                # every Nth playlist is the previous one
    playlist_error_until: float = 0.0                   # 500 on playlist for t seconds after begin()
    batch_segments: int = 1                             # playlist advances N segments at a time
    redirect_segments_to: str = ""                      # absolute base for segment URIs


class SimOrigin:
    """Live origin: entry i becomes available at start + sum(durations[:i+1])."""

    def __init__(self, timeline: list, window: int = 4, faults: Faults | None = None,
                 master: bool = True, preload: int | None = None, time_scale: float = 1.0):
        self.timeline = timeline
        self.window = window
        self.faults = faults or Faults()
        self.master = master
        self.time_scale = time_scale
        self.lock = threading.Lock()
        self.requests: dict = {}
        self.segment_requests: list = []
        self.token = 0
        self.playlist_count = 0
        self.last_playlist = None
        self.preload = window if preload is None else preload
        ends, acc = [], 0.0
        for e in timeline:
            acc += e.duration
            ends.append(acc)
        self.ends = ends
        self.start = None
        self.by_name = {}
        for e in timeline:
            self.by_name.setdefault(e.name, []).append(e)
        handler = self._make_handler()
        self.server = ThreadingHTTPServer(("127.0.0.1", 0), handler)
        self.server.daemon_threads = True
        self.port = self.server.server_address[1]
        self.base = f"http://127.0.0.1:{self.port}"
        self.thread = threading.Thread(target=self.server.serve_forever, daemon=True)

    # live clock -------------------------------------------------------
    def begin(self):
        offset = self.ends[self.preload - 1] if self.preload else 0.0
        self.start = time.monotonic() - offset / self.time_scale
        self.begin_wall = time.monotonic()
        self.thread.start()
        return self

    def elapsed(self) -> float:
        return (time.monotonic() - self.start) * self.time_scale

    def available(self) -> int:
        t = self.elapsed()
        n = 0
        while n < len(self.ends) and self.ends[n] <= t + 1e-9:
            n += 1
        b = max(1, self.faults.batch_segments)
        if n < len(self.ends):
            n -= n % b
        return n

    def finished(self) -> bool:
        return self.available() >= len(self.timeline)

    def stop(self):
        self.server.shutdown()
        self.server.server_close()

    # playlists ----------------------------------------------------------
    def media_text(self) -> str:
        n = self.available()
        win = self.timeline[max(0, n - self.window):n]
        if not win:
            win = self.timeline[:1]
        target = max(1, int(max(e.duration for e in win) + 0.999))
        tok = f"?token={self.token}" if self.faults.rotate_tokens else ""
        base = self.faults.redirect_segments_to
        lines = ["#EXTM3U", "#EXT-X-VERSION:3", f"#EXT-X-TARGETDURATION:{target}",
                 f"#EXT-X-MEDIA-SEQUENCE:{win[0].seq}"]
        for e in win:
            if e.discontinuity:
                lines.append("#EXT-X-DISCONTINUITY")
            lines.append(f"#EXTINF:{e.duration:.3f},")
            lines.append(f"{base}seg/{e.name}{tok}")
        return "\n".join(lines) + "\n"

    def master_text(self) -> str:
        tok = f"?token={self.token}" if self.faults.rotate_tokens else ""
        return ("#EXTM3U\n#EXT-X-STREAM-INF:BANDWIDTH=11520000,RESOLUTION=1920x1080,"
                'CODECS="avc1.640028,ac-3"\n' + f"media.m3u8{tok}\n")

    # http ---------------------------------------------------------------
    def _count(self, key):
        with self.lock:
            self.requests[key] = self.requests.get(key, 0) + 1

    def _make_handler(self):
        origin = self

        class H(BaseHTTPRequestHandler):
            protocol_version = "HTTP/1.1"

            def log_message(self, *a):
                pass

            def _send(self, code, body, ctype="text/plain", extra=None):
                self.send_response(code)
                self.send_header("Content-Type", ctype)
                self.send_header("Content-Length", str(len(body)))
                for k, v in (extra or {}).items():
                    self.send_header(k, v)
                self.end_headers()
                self.wfile.write(body)

            def do_GET(self):
                path, _, query = self.path.partition("?")
                f = origin.faults
                if f.rotate_tokens and path != "/master.m3u8" and not path.startswith("/edge/master"):
                    if not query.startswith("token="):
                        return self._send(403, b"token required")
                if path == "/master.m3u8":
                    origin._count("master")
                    with origin.lock:
                        if f.rotate_tokens:
                            origin.token += 1
                    if f.redirect_master:
                        return self._send(302, b"", extra={"Location": f"{origin.base}/edge/master.m3u8"})
                    return self._send(200, origin.master_text().encode(), "application/vnd.apple.mpegurl")
                if path == "/edge/master.m3u8":
                    origin._count("master")
                    return self._send(200, origin.master_text().encode(), "application/vnd.apple.mpegurl")
                if path in ("/media.m3u8", "/edge/media.m3u8"):
                    if f.redirect_master and path == "/media.m3u8":
                        # only the edge (post-redirect) location knows the stream
                        return self._send(404, b"wrong host/path")
                    origin._count("media")
                    if time.monotonic() - origin.begin_wall < f.playlist_error_until:
                        return self._send(500, b"origin busy")
                    with origin.lock:
                        origin.playlist_count += 1
                        if f.rotate_tokens:
                            origin.token += 1
                        text = origin.media_text()
                        if f.stale_every and origin.playlist_count % f.stale_every == 0 and origin.last_playlist:
                            text = origin.last_playlist
                        origin.last_playlist = text
                    return self._send(200, text.encode(), "application/vnd.apple.mpegurl")
                m = re.fullmatch(r"(?:/edge)?/seg/(.+)", path)
                if not m:
                    return self._send(404, b"nope")
                name = m.group(1)
                origin._count("segment")
                with origin.lock:
                    origin.segment_requests.append(name)
                entries = origin.by_name.get(name)
                if not entries or name in f.missing:
                    return self._send(404, b"missing")
                # latest entry with that name that is already available
                avail = origin.available()
                cands = [e for e in entries if origin.timeline.index(e) < avail] or entries
                body = cands[-1].payload
                with origin.lock:
                    trunc = f.truncate.get(name, 0)
                    if trunc:
                        f.truncate[name] = trunc - 1
                    stall = f.stall.get(name, 0)
                    if stall:
                        f.stall[name] = stall - 1
                self.send_response(200)
                self.send_header("Content-Type", "video/mp2t")
                self.send_header("Content-Length", str(len(body)))
                self.end_headers()
                try:
                    if trunc:
                        self.wfile.write(body[: len(body) * 2 // 3])
                        self.wfile.flush()
                        self.close_connection = True
                        return
                    if stall:
                        self.wfile.write(body[: len(body) // 2])
                        self.wfile.flush()
                        time.sleep(f.stall_seconds)
                        self.close_connection = True
                        return
                    if f.throttle_bps:
                        chunk = 2048
                        for i in range(0, len(body), chunk):
                            time.sleep(min(chunk, len(body) - i) / f.throttle_bps)
                            self.wfile.write(body[i:i + chunk])
                            self.wfile.flush()
                    else:
                        self.wfile.write(body)
                except (BrokenPipeError, ConnectionResetError):
                    pass

        return H

    @property
    def source_url(self) -> str:
        return f"{self.base}/master.m3u8" if self.master else f"{self.base}/media.m3u8"
